cultural_concepts: {'id': 'jeong_001', 'concept': '정 (情)', 'romanization': 'Jeong', 'description': '한국 특유의 정서적 유대감과 애착, 깊은 인간관계의 정서', 'counseling_implications': ['관계 중심의 상담 접근 중요', '상담자-내담자 간 따뜻한 관계 형성 필수', '정이 깊으면 헤어짐이 더 힘들 수 있음', '정 때문에 해로운 관계를 유지하는 경우 탐색'], 'helpful_phrases': ['오랜 관계에서 쌓인 정이 있으시군요.', '정 때문에 더 힘드실 수 있어요.', '관계를 소중히 여기시는 마음이 느껴져요.']}, {'id': 'chemyeon_001', 'concept': '체면 (體面)', 'romanization': 'Chemyeon', 'description': '사회적 이미지와 명예를 중시하는 문화적 가치', 'counseling_implications': ['체면 때문에 도움 요청이 어려울 수 있음', '가족이나 집단의 체면 손상 우려', '실패나 문제를 숨기려는 경향', '상담 자체에 대한 부끄러움'], 'helpful_phrases': ['상담받는 것이 부끄러운 일이 아니에요.', '도움을 요청하는 것은 용기 있는 행동이에요.', '다른 사람들 눈이 신경 쓰이시는군요.']}, {'id': 'hyo_001', 'concept': '효 (孝)', 'romanization': 'Hyo', 'description': '부모에 대한 공경과 효도를 강조하는 전통적 가치', 'counseling_implications': ['부모와의 갈등에서 죄책감을 느낄 수 있음', '부모의 기대와 자신의 욕구 사이 갈등', '부모 돌봄의 부담과 스트레스', '세대 간 가치관 차이로 인한 어려움'], 'helpful_phrases': ['부모님께 효도하고 싶은 마음과 자신의 삶을 살고 싶은 마음, 둘 다 자연스러운 거예요.', '부모님의 기대가 부담스러우시군요.', '자신을 돌보는 것도 중요해요.']}, {'id': 'nunchi_001', 'concept': '눈치', 'romanization': 'Nunchi', 'description': '상황과 타인의 감정을 살피는 사회적 감수성', 'counseling_implications': ['타인의 기분에 지나치게 민감할 수 있음', '자신의 욕구보다 타인의 기대에 맞추려 함', '직접적 표현보다 간접적 소통 선호', '거절하기 어려움'], 'helpful_phrases': ['다른 사람 눈치를 많이 보시는군요.', '자신의 감정과 필요도 중요해요.', '모든 사람을 만족시킬 수는 없어요.']}, {'id': 'han_001', 'concept': '한 (恨)', 'romanization': 'Han', 'description': '오랜 시간 억눌린 슬픔, 원망, 서러움의 복합 정서', 'counseling_implications': ['오래 쌓인 감정의 표현과 해소 필요', '세대를 넘어 전달되는 트라우마', '억압된 감정의 신체화 가능성', '충분한 공감과 경청의 중요성'], 'helpful_phrases': ['오랜 시간 마음에 담아두셨군요.', '그 서러움을 충분히 느끼셔도 돼요.', '이야기하시면서 조금이라도 풀리시면 좋겠어요.']}, {'id': 'ppalli_001', 'concept': '빨리빨리 문화', 'romanization': 'Ppalli-ppalli', 'description': '빠른 속도와 효율을 추구하는 문화적 특성', 'counseling_implications': ['빠른 해결책을 원할 수 있음', '상담 과정의 시간이 필요함을 설명', '조급함과 인내의 균형', '자신에게 시간을 주는 것의 중요성'], 'helpful_phrases': ['천천히 해도 괜찮아요.', '변화에는 시간이 필요해요.', '빨리 나아지려 하지 않으셔도 돼요.']}, {'id': 'collectivism_001', 'concept': '집단주의 (집단 중심)', 'romanization': 'Jipdanjuui', 'description': '개인보다 집단(가족, 회사, 학교)을 우선시하는 가치관', 'counseling_implications': ['개인의 욕구 표현에 죄책감 느낄 수 있음', "'나'보다 '우리'를 먼저 생각하는 습관", '집단에서 튀면 안 된다는 압박', '개인의 행복 추구에 대한 갈등'], 'helpful_phrases': ['개인의 필요를 챙기는 것도 중요해요.', '나를 돌보는 것이 이기적인 게 아니에요.', '가끔은 자신을 먼저 생각해도 괜찮아요.']}, {'id': 'comparison_001', 'concept': '비교 문화', 'romanization': 'Bigyo Munhwa', 'description': '끊임없이 타인과 비교하는 사회적 경향', 'counseling_implications': ['상대적 박탈감과 열등감', 'SNS로 인한 비교 심화', '성취와 외모에 대한 과도한 비교', '자존감 저하의 주요 원인'], 'helpful_phrases': ['비교는 끝이 없어요. 자신의 속도를 존중해 주세요.', '남과 비교하면 힘들어지기 쉬워요.', '자신만의 기준으로 살아도 괜찮아요.']}, {'id': 'success_pressure_001', 'concept': '성공 압박', 'romanization': 'Seonggong Appak', 'description': '사회적 성공(학벌, 직장, 재정)에 대한 강한 압박', 'counseling_implications': ['실패에 대한 극도의 두려움', '완벽주의 성향 발달', '번아웃 위험성', '자기 가치를 성취로만 측정'], 'helpful_phrases': ['성공만이 전부가 아니에요.', '실패해도 괜찮아요. 그것도 경험이에요.', '자신에게 조금 더 관대해져도 돼요.']}, {'id': 'marriage_pressure_001', 'concept': '결혼/출산 압박', 'romanization': 'Gyeolhon Appak', 'description': '적절한 나이에 결혼하고 아이를 낳아야 한다는 사회적 기대', 'counseling_implications': ['명절 스트레스 (결혼/출산 질문)', '비혼/비출산 선택에 대한 죄책감', '나이에 대한 압박감', '부모님 실망시키기 두려움'], 'helpful_phrases': ['결혼 여부와 관계없이 가치 있는 삶을 살 수 있어요.', '자신의 선택을 존중해 주세요.', '남들의 기준에 맞출 필요 없어요.']}

